import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_SIZE = 1000007;
    static final long MOD_VALUE = 1000000007L;
    static int p_value, k_value;
    static int[] count_array = new int[MAX_SIZE];
    static int[] visited = new int[MAX_SIZE];
    static int[] count_num = new int[MAX_SIZE];
    static List<Integer> divisors = new ArrayList<>();

    static void explore(int x, int start) {
        int count = 1;
        while ((long)k_value * x % p_value != start) {
            x = (int)((long)k_value * x % p_value);
            visited[x] = 1;
            count++;
        }
        count_num[count]++;
    }

    static boolean isPrimeNumber(int x) {
        if (x < 2) return false;
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        p_value = Integer.parseInt(st.nextToken());
        k_value = Integer.parseInt(st.nextToken());

        if (k_value == 0) {
            long total = 1;
            for (int i = 1; i < p_value; i++) {
                total = (total * p_value) % MOD_VALUE;
            }
            System.out.println(total);
            return;
        }

        for (int i = 0; i < p_value; i++) {
            if (visited[i] == 0) {
                explore(i, i);
            }
        }

        for (int i = 1; i <= p_value; i++) {
            if (count_num[i] != 0) {
                divisors.add(i);
            }
        }

        long result = 1;
        for (int i = 0; i < divisors.size(); i++) {
            long temp_sum = 0;
            int divisor_i = divisors.get(i);
            for (int j = 0; j < divisors.size() && (long)divisors.get(j) * divisors.get(j) <= divisor_i; j++) {
                int divisor_j = divisors.get(j);
                if (divisor_i % divisor_j == 0) {
                    int a = divisor_i / divisor_j;
                    int b = divisor_j;
                    temp_sum += (long)a * count_num[a];
                    if (a != b) temp_sum += (long)b * count_num[b];
                    temp_sum %= MOD_VALUE;
                }
            }
            int count = count_num[divisor_i];
            for (int j = 0; j < count; j++) {
                result = (result * temp_sum) % MOD_VALUE;
            }
        }
        System.out.println(result);
    }
}
